import{_ as e,o as a,c as i,a0 as t}from"./chunks/framework.OED5XGjC.js";const k=JSON.parse('{"title":"Run the daily agent loop","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/agent-loop.md","filePath":"how-to/agent-loop.md"}'),n={name:"how-to/agent-loop.md"};function h(o,s,l,d,p,r){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="run-the-daily-agent-loop" tabindex="-1">Run the daily agent loop <a class="header-anchor" href="#run-the-daily-agent-loop" aria-label="Permalink to &quot;Run the daily agent loop&quot;">​</a></h1><p>The core loop for an agent (or a human driving like one): orient → claim → work → hand off → resume. Every step is a verb; <code>--json</code> on all of them.</p><h2 id="orient" tabindex="-1">Orient <a class="header-anchor" href="#orient" aria-label="Permalink to &quot;Orient&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prompt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # token-sized digest, sized for a context window</span></span></code></pre></div><p><code>status --prompt</code> is the session opener: counts by kind, what&#39;s in progress, what&#39;s open — enough to pick work without reading the files. <code>myco status</code> (no flag) is the human-readable version; <code>myco board</code> and <code>myco report</code> give the kanban and the trend. Boards cap at a screenful of rows — <code>--all</code> shows every card. For a human at the wheel, <code>myco ui</code> is the same board as a full-screen TUI — see <a href="./../getting-started.html#the-interactive-board">the interactive board</a>.</p><h2 id="claim" tabindex="-1">Claim <a class="header-anchor" href="#claim" aria-label="Permalink to &quot;Claim&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claimed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --owner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> item</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in-progress</span></span></code></pre></div><p><code>claimed</code> says &quot;an actor owns this&quot; before work starts; <code>in-progress</code> says &quot;being worked now&quot;. Both are single legal steps from <code>open</code>. Owner ids are namespaced actor strings — <code>devin</code>, <code>human:luis</code>, … — so multiple agents can share a ledger.</p><p>Hit a wall mid-task: <code>myco item set T-012 --status blocked</code>. Need the details: <code>myco item show T-012</code> (add <code>--json</code> for the full item + location + body).</p><h2 id="hand-off" tabindex="-1">Hand off <a class="header-anchor" href="#hand-off" aria-label="Permalink to &quot;Hand off&quot;">​</a></h2><p>Before the session ends, leave resumable state on the item:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> handoff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --actor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --note</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Done: parser landed. Next: emitter. Open: archive semantics.&quot;</span></span></code></pre></div><p><code>--note -</code> reads stdin — pipe a generated summary. See <a href="./handoff.html">handoffs</a> for the full verb behavior.</p><h2 id="resume" tabindex="-1">Resume <a class="header-anchor" href="#resume" aria-label="Permalink to &quot;Resume&quot;">​</a></h2><p>Next session — human or agent — pulls the restart context:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # compact prompt-ready block</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> T-012</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # {item, location, blocks_titles, handoffs, open_checklist}</span></span></code></pre></div><p>Then <code>myco status --prompt</code> for the ledger-wide picture and the loop restarts.</p><h2 id="hygiene" tabindex="-1">Hygiene <a class="header-anchor" href="#hygiene" aria-label="Permalink to &quot;Hygiene&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # exits 1 with findings</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # safe repairs + one commit</span></span></code></pre></div><p>Run <code>check</code> when files were hand-edited or the index may have drifted — it validates the <a href="./../explanation/file-spec.html">file spec</a>, state machine, and index snapshots.</p><h2 id="no-commit-mode" tabindex="-1">No-commit mode <a class="header-anchor" href="#no-commit-mode" aria-label="Permalink to &quot;No-commit mode&quot;">​</a></h2><p>Batch or scripted flows can skip the per-verb commit with <code>--no-commit</code> or <code>MYCO_NO_COMMIT=1</code>, then commit once:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;chore: end-of-day ledger tidy&quot;</span></span></code></pre></div><p><code>myco commit</code> stages all worktree changes and commits with a conventional message (default <code>chore: update project ledger</code>).</p>`,24)])])}const g=e(n,[["render",h]]);export{k as __pageData,g as default};
